import java.util.Scanner;

public class Main {
    public static int run(int n, int m) {
        if (n <= 3) {
            return 0;
        }
        int prev_ans = 17;
        int curr_ans = 17;
        int max_len = (n - 1) * (n - 2) / 2 + 1;
        int toggle_bit = 1;
        int[][] dp = new int[2][max_len + 1];
        // Initialize dp[0][0..3]
        dp[0][0] = 1;
        dp[0][1] = 2;
        dp[0][2] = 2;
        dp[0][3] = 1;
        for (int length = 4; length < n; length++) {
            int total_pairs = length * (length - 1) / 2;
            curr_ans = (length + 1) * prev_ans;
            int cum_sum = 0;
            // Compute dp[toggle_bit][i] for i in [0, length)
            for (int i = 0; i < length; i++) {
                cum_sum += dp[toggle_bit ^ 1][i];
                cum_sum %= m;
                dp[toggle_bit][i] = cum_sum;
            }
            // Compute dp[toggle_bit][i] for i in [length, total_pairs/2]
            for (int i = length; i <= total_pairs / 2; i++) {
                cum_sum += dp[toggle_bit ^ 1][i];
                cum_sum -= dp[toggle_bit ^ 1][i - length];
                cum_sum %= m;
                if (cum_sum < 0) {
                    cum_sum += m;
                }
                dp[toggle_bit][i] = cum_sum;
            }
            // Mirror the values for i in [total_pairs/2 + 1, total_pairs]
            for (int i = 0; i <= total_pairs / 2; i++) {
                dp[toggle_bit][total_pairs - i] = dp[toggle_bit][i];
            }
            int total = 0;
            for (int i = 0; i < total_pairs; i++) {
                int temp_total = 0;
                int start_j = Math.max(1, -total_pairs + i + length + 2);
                for (int j = start_j; j <= length; j++) {
                    int index = length + 2 - j + i;
                    if (index >= 0 && index <= max_len) {
                        temp_total += j * dp[toggle_bit][index];
                    }
                }
                total += dp[toggle_bit][i];
                total %= m;
                temp_total %= m;
                curr_ans += temp_total * total;
                curr_ans %= m;
            }
            prev_ans = curr_ans;
            toggle_bit ^= 1;
        }
        return Math.floorMod(curr_ans, m);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = scanner.nextInt();
        System.out.println(run(n, m));
        scanner.close();
    }
}
